quests[94379] = { id = 94379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Old Hearth", description = "It looks like your house is ready for an upgrade. This doesn't normally happen so fast, but you've really made an impression around here.\n\nHead on over to our general contractor for next steps.", progress = "Did you get your house upgraded?", completion = "Did the renovation go well? I hope it gives you a little more room for all the treasures you find in your adventures.\n\nBe sure to visit the general contractor again when you're next ready for an upgrade.\n\nOh, and a letter arrived for you while you were away.", objectives = "Level up your house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94388] = { id = 94388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Time's a Choice", description = "A little lesson. Trying to fool me twice is a grave error.\n\nMy dim-witted pupil has yet to return from their rendezvous with their acquaintance. Normally I would not bat an eye, but he has a journal of mine. I want that journal back.\n\nWould you be a dear and remind him?", completion = "<Magister Meledor appears to be lost in thought...>", objectives = "Remind Magister Meledor in the West Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94390] = { id = 94390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: A Hunter's Regret" }
quests[94391] = { id = 94391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Push Back the Light" }
quests[94393] = { id = 94393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Career Counseling", description = "How good are you at teaching, {name}?\n\nOne of my pupils, Kyltus, has been having particular trouble with deciding what path along the road of life he wants to pursue. \n\nPerhaps a talk with you will aid his tumultuous heart?", completion = "Instructor Thalendir sent you?! I will have to give him my apologies.\n\nBut I am glad you are here. Could you lend me an ear?", objectives = "Check in on Kyltus Bloodburn in the Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94396] = { id = 94396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down a Peg", description = "There seems to be a problem student at the academy.\n\nI have heard reports that a student, Tytalor Goldenblade, is stirring up trouble in Sunstrider Isle. I'd go myself but I have my hands full running practice here already.\n\nCould you go check on him and... educate him of his misgivings?", completion = "Truly, I am incredibly talented!\n\n<Tytalor appears to be lost within his own thoughts.>", objectives = "Check in on Tytalor Goldenblade in the Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94408] = { id = 94408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contract of Service", description = "It is not honor or glory that drives your kind to war...it is gold. You and your enemies are always paid for the blood you spill upon the battlefield.\n\nEvery enemy you slay in Slayer's Rise carries a contract from Ziadan. Bring me those contracts, and I will pay you what their loyalty once cost her.", progress = "Are you here to deliver their contracts?", completion = "See I was correct. In the end the price of blood is always in gold.", objectives = "Collect 10 Contracts of Service off slain players in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94409] = { id = 94409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contract of Service", description = "It is not honor or glory that drives your kind to war...it is gold. You and your enemies are always paid for the blood you spill upon the battlefield.\n\nEvery enemy you slay in Slayer's Rise carries a contract from Vidious. Bring me those contracts, and I will pay you what their loyalty once cost her", progress = "Are you here to deliver their contracts?", completion = "See I was correct. In the end the price of blood is always in gold.", objectives = "Collect 10 Contracts of Service off slain players in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94415] = { id = 94415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plumbing the Void", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94416] = { id = 94416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rehoming Technology", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has allowed you to take a small selection of our technology back to your world, if you choose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94417] = { id = 94417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crests of the Dawn", description = "Using what I've learned from Silvermoon's artisans, Cuzolth and I can infuse your gear with additional power!\n\nPowerful equipment requires Dawncrests to upgrade it to its full potential. These crests are rewarded through many different activities. Dawncrests have five tiers, and more dangerous tasks reward you with higher-tier crests. Adventurer Dawncrests are the lowest tier, but still quite powerful!\n\nBring me thirty Adventurer Dawncrests and we can help you upgrade your gear further.", progress = "If you're having a hard time finding Adventurer Dawncrests, you can search for hidden treasures around Eversong, Zul'Aman, Harandar, and Voidstorm. There's no shortage of those treasures!", completion = "This is wonderful. I'm excited for you to grow in power!\n\nAnd to advance my research, of course. But yes, your power is my top priority!", objectives = "Acquire 30 Adventurer Dawncrests by defeating unique creatures, completing world activities, or by looting caches. Speak to Cuzolth to upgrade an Adventurer track item using those crests, then return to Vaskarn in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94418] = { id = 94418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crest Transmutation", description = "Did you know that crests can be transmuted into different tiers?\n\nIf you find yourself with crests that are too powerful for the gear you've acquired, I can help you transmute those crests into lower tiers that you can use.\n\nAnd once all of your gear is sufficiently powerful, I'll be able to transmute your spare lower crests into higher ones!\n\nLet's practice the transmutation process. Here's a few Veteran Dawncrests. Speak to me and I can transform them into Adventurer Dawncrests for you.", progress = "If you lose those Veteran Dawncrests, you can find more from powerful creatures around Eversong, Zul'Aman, Harandar, and Voidstorm. I've heard there's quite a variety of them!", completion = "Remarkable!\n\nKeep in mind I can only transmute crests into a higher tier when you have outgrown their usefulness, and it will be a costly process. Thank you for all of your help, {name}!", objectives = "Bring 10 Veteran Dawncrests to Vaskarn in Silvermoon, then trade them for a Bundle of Adventurer Dawncrests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94423] = { id = 94423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanctum Secure", description = "Our control here is only the beginning. Xal'atath has left other pockets of anomalies across the land. The defenses we've devised here can be used to secure those areas as well.\n\nTravel to Sunkiller Sanctum and construct five additional defenses to solidify our hold on that location.\n\nI will supply the Stormarion Core necessary to activate those defenses.", objectives = "Deploy 3 defenses at Sunkiller Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94430] = { id = 94430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventuring Gear", description = "{name}, you're just in time! I was exchanging research notes with the artisans here in Silvermoon all day. Did you know they can infuse weapons and armor with the power of the dawn itself? Fascinating!\n\nI've been itching to put some of these new techniques to the test. Bring me a piece of Adventurer equipment and I'll let you know what we need to make it more powerful.\n\nThere should be plenty of people in Silvermoon and beyond willing to reward you with some Adventurer equipment in exchange for your aid.", completion = "This piece of equipment will be perfect!\n\nI can help you make this more powerful, but we'll need some reagents.", objectives = "Obtain a piece of Adventurer track gear, then return to Vaskarn in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94432] = { id = 94432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran Equipment", description = "We have only just begun to scratch the surface of how powerful your gear can become!\n\nHowever, every piece of equipment has a limit to how much it can be upgraded. The more powerful an item is at its baseline, the more powerful it will become as we upgrade it. An item's upgrade track determines which crests we must use to upgrade it.\n\nBring me a piece of Veteran equipment this time along with ten Veteran Dawncrests. Just like before, Cuzolth will help you upgrade the item using those crests.", progress = "If you're having trouble finding a piece of Veteran equipment, try completing a Heroic dungeon or a challenging weekly activity in Eversong, Zul'Aman, Harandar, or Voidstorm. You can find more powerful gear this way!", completion = "You're a natural! It looks like you have a handle on things already.\n\nEvery time you want to upgrade a piece of equipment, the process works the same way. Bring us the item and the crests that go with it, then Cuzolth will help you upgrade it.", objectives = "Obtain a piece of Veteran track gear and 10 Veteran Dawncrests. Speak to Cuzolth to upgrade a Veteran track item using those crests, then return to Vaskarn in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94444] = { id = 94444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choose a Path", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", completion = "Carry your traditions with pride, for their roots intertwine within you.\n\nAln'hara bless your path.", objectives = "Talk to Chromie in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94445] = { id = 94445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choose a Path", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Say, you look like someone who appreciates the great outdoors! Elwynn is lovely this time of year.\n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of yours is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", completion = "Carry your traditions with pride, for their roots intertwine within you.\n\nAln'hara bless your path.", objectives = "Talk to Chromie in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94450] = { id = 94450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twenty Five Percent Completed", description = "We're still getting things setup for rewarding endeavors. This is a temporary quest to grant you community coupons.\n\ncommunity coupons will normally be earned by completing endeavor tasks, not via a quest like this." }
quests[94451] = { id = 94451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fifty Percent Completed", description = "We're still getting things setup for rewarding endeavors. This is a temporary quest to grant you community coupons. \n\ncommunity coupons will normally be earned by completing endeavor tasks, not via a quest like this." }
quests[94452] = { id = 94452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seventy Five Percent Completed", description = "We're still getting things setup for rewarding endeavors. This is a temporary quest to grant you community coupons. \n\ncommunity coupons will normally be earned by completing endeavor tasks, not via a quest like this." }
quests[94453] = { id = 94453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Hundred Percent Completed", description = "We're still getting things setup for rewarding endeavors. This is a temporary quest to grant you community coupons. \n\ncommunity coupons will normally be earned by completing endeavor tasks, not via a quest like this." }
quests[94455] = { id = 94455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home at Last", description = "It's time to cross the threshold into a new chapter.", objectives = "Approach your front door and enter your new house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94457] = { id = 94457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Battlegrounds", description = "Battlegrounds stand as crucible where soldiers clash for honor, resources, and glory.\n\nEach victory hones your skill and strengthens your resolve.\n\nGo, test yourself against worthy foes and bring pride to your banner.You will learn:", sourceObjective = "Complete any Battleground in Midnight.", sourceObjectiveStatus = "unverified-source-field" }
quests[94464] = { id = 94464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heritage of the Haranir", description = "You have travelled far and learned much of Aln'hara's grace.\n\nIt is time to return home and share the wisdom you have earned with your people.", completion = "You have seen many battles and met many peoples. Your journeys continue to bring us closer to the wisdom and grace of Aln'hara. \n\nSince you left, roots and vines began to rapidly grow within your old home. Eventually, their purpose became clear: armor, grown for you from the roots of the great trees as a blessing from Aln'hara herself!\n\nWear it with pride as you continue your journey, {name}. Thank you.", objectives = "Tell Orweyna of your travels at the Den in Harandar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94469] = { id = 94469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Handful of Voidlight Marl", objectives = "Thanks to you, the singularity anchor survived another assault. Take this as a sign of our appreciation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94470] = { id = 94470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cluster of Voidlight Marl" }
quests[94471] = { id = 94471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trove of Voidlight Marl" }
quests[94474] = { id = 94474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Vault", description = "In wake of recent events, the Vanguard of the Light has recovered and preserved relics of exceptional power and craftsmanship. To safeguard these treasures from prying eyes, the Magisters of Silvermoon have conjured a vault within Silvermoon's bank.\n\nOnly the most proven of champions may earn the right to draw from its splendor. If the Light deems you worthy, you may be bestowed an artifact of great power.", objectives = "Obtain a piece of loot from the Great Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94477] = { id = 94477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Voidspire: Flicker in the Hollow", description = "There's little light in these lands. What remains is fractured, hidden, or fading.\n\nFetch me Echoes of Radiance and I will grant you passage where no path should exist.", objectives = "Collect 3 Echoes of Radiance within The Voidspire on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94478] = { id = 94478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary of Silvermoon Court" }
