quests[94790] = { id = 94790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Research Console: Exploring the Void", description = "No rest for the researchers, as they say.\n\nAs much as I would love to go traipsing around this blasted voidscape, I need to remain at this post. But you! You can be our eyes and ears in the abyss.\n\nGo and explore the Voidstorm, maybe we can find some additional samples to feed into the console.", completion = "More samples, excellent! The console hungers...", objectives = "Complete 3 World Quests for Void Researcher Anomander in Howling Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94794] = { id = 94794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fine Fashion Funding", objectives = "Thank you for your assistance. Please accept this token as thanks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94795] = { id = 94795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Agents of the Shield" }
quests[94808] = { id = 94808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Midnight - Normal Random - 1st" }
