quests[94816] = { id = 94816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fine Fashion Funding", objectives = "Thank you for your assistance. Please accept this token as thanks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94831] = { id = 94831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Idol in Hand", description = "<The idol appears to be a figure of Ohn'ahra carved from serevite, an ore used in many titan temples.\n\nPreservationist Kathos would surely be interested in this.>", objectives = "Return the Idol of Ohn'ahra to Preservationist Kathos in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94834] = { id = 94834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings of Abundance", description = "<This idol proves the depth of your bond with abundance.\n\nSpeak with Du'gal at the Altar of Blessings in Amani'Zar to begin worshipping Dundun.>", completion = "Ah, an Idol of Abundance.\n\nDe lord of glory and plentitude must favor you highly above his many other acolytes.", objectives = "Speak with Du'gal at the Altar of Blessings in Amani'Zar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94839] = { id = 94839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings of Peril", description = "<This idol proves the depth of your bond with peril.\n\nSpeak with Du'gal at the Altar of Blessings in Amani'Zar to begin worshipping Puul.>", completion = "An Idol of Peril...\n\nMany shy away from de realm of perils. There is much danger surroundin' de immense power Puul blesses their worshippers with.\n\nWill you risk your life for it?", objectives = "Speak with Du'gal at the Altar of Blessings in Amani'Zar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94844] = { id = 94844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: For My Horde", description = "We must repel this attack.\n\nYour Horde is strong. You do not give in to the hypocritical claims of the Alliance. You do not let them besmirch your honor.\n\nI want my forces to learn from you. Go, take this Voidclarion. Use it to inspire my void minions.\n\nLet them see the power of the Horde.", completion = "Good. My minions must grow stronger.", objectives = "Empower 8 Hatebound forces at the Bastion of Might in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94845] = { id = 94845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: The Bastion of Might", description = "Vidious presses an attack. I do not see this Alliance he recruited, but monsters.\n\nIllogical. Vidious would not recruit another force until we had our fun with the recent additions.\n\nFight these monsters. Find out what they are. Bring me evidence.\n\nPerhaps you need a cause to fight for beyond amusement? If Vidious tires of me, he will turn his conquest to Azeroth next. You'll want to stop that, right?\n\nThen aid me.", progress = "What trickery have you found?", completion = "Shadowgraft? Pathetic.\n\nOnly domanaar with less skill and intelligence use it. It empowers creatures--makes them blind with violent urges.\n\nBut the creatures lose all cunning. All interest. It is a single flavor, not the complex notes of heartache and betrayal. It is boring.", objectives = "Collect 12 Spiteful Shadowgraft from wild creatures in the Bastion of Might.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94847] = { id = 94847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations Underway", description = "As you may or may not recall, I once helped young paladins obtain their first armored mount.\n\nIt was a tedious task that involved months of obtaining materials and sending them all over Azeroth.\n\nThankfully, times have changed and we now have most of those materials at hand. That being said, I wish to help you obtain a new mount, something worthy of your title as Highlord.\n\nIn order for us to begin, I only require that you obtain a barding for us. Something strong, thick, and heavy.", completion = "<Grayson examines the barding.>\n\nThis is... well, a good start, Highlord. But I think it will have to be strengthened a bit.", objectives = "Obtain a Stonehide Leather Barding from a leatherworker. You may also obtain it from the auction house if you're not a leatherworker or don't know a leatherworker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94848] = { id = 94848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: Pre-Provoked Violence", description = "Vidious, using shadowgraft? Unbelievable. He is better than this.\n\nHow dare he disappoint me.\n\nI need no shadowgraft to convince mighty {class}s like you to fight for me.\n\nShow him the error of his ways before he disappoints me further and abandons this conflict in favor of helping Xal'atath conquer Azeroth.\n\nTake the fight to him. Siege his bastion. And if you do not wish to stain your hands with Alliance blood, there are many void minions awaiting your prowess.", completion = "So, Vidious is also under attack by shadowgrafted monsters? \n\nI see. \n\n<Ziadan almost smiles.> \n\nSo, he did not betray my expectations after all. Perhaps we keep him alive a little longer. \n\nBut there is a third. An interloper.", objectives = "Slay Void creatures or players in the Bastion of Valor in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94849] = { id = 94849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: A Familiar Grudge", description = "Vidious will have a favorite, much like I do: a mortal from your world filled with grief turned to violence.\n\nThey do not have the support of your leaders, but they will always have support from us domanaar.\n\nFind this favorite. I hear of a warlock that has slain many Horde. I feel their grief wafting in the air. They are so lost in it, they would give up the war to save Azeroth for a chance to kill your people.\n\nGo. Savor the fight.", completion = "Good work. The mortal was blinded by their pain, so they never would have listened to reason. \n\nAll they cared for anymore was the fight.", objectives = "Slay Emrin Sparkpox at the Bastion of Valor in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94850] = { id = 94850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If You Build It", description = "If we wish to achieve a sustained connection to Xoroth, we'll need a particularly resilient portal. Unfortunately, we can't just summon this one up from the ground.\n\nI will need you to gather the requisite materials. Once we have them, I will have the mo'arg begin construction at once. \n\nHere's the list of what you'll need.", completion = "Excellent. This Unbending Potion should shore up the Felslate enough to hold the portal's structure, and these Chaotic Spinel crystals should focus the portal's magic nicely.\n\nI will set the mo'arg to work posthaste.", objectives = "Collect 5 Felslate, 3 Chaotic Spinel and an Unbending Potion. These can be gathered and crafted using profession skills or purchased on the Auction House.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94855] = { id = 94855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: Setting It Aside", description = "So, we have another enemy? One who would get in between me and Vidious?\n\n<Ziadan tightens her fist around her weapon.>\n\nUnacceptable.\n\nThe Voidscar Arena to the north is the most strategic position outside of our bastions. An interloping domanaar will have staged their forces there, I guarantee it.\n\nI can set aside my quarrel with Vidious long enough to deal with this shared threat. Fortunately for you, he hasn't brought his Alliance forces with him.", completion = "Who dares stage forces here? Without announcing themselves?\n\nNoxian? Decimus? We will root them out and make them pay.", objectives = "Meet the domanaar at the Voidscar Arena in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94865] = { id = 94865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: What Remains of a Temple Broken" }
quests[94866] = { id = 94866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Ours Once More!" }
quests[94867] = { id = 94867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in Atal'Abasi", description = "Tolbani and Jehnira have been missin' for some time. Last I heard, dey were scoutin' Atal'Abasi for supplies.\n\nThat area is covered in murlocs. Too many of 'em is dangerous even for an Amani.\n\nFind dem and make sure dey alright!", completion = "Vakala sent you? She was right to think dis place was dangerous.", objectives = "Find Tolbani and Jehnira in Atal'Abasi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94868] = { id = 94868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Takes Two", description = "Jan'alai is a hen! And that means eggs! It takes two hatchers to safely hatch her eggs. Find Brek's niece - he will teach you both the ceremony." }
quests[94869] = { id = 94869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry Hungry Hatchlings", description = "The hatchlings will be hungry! Collect meat from the crabs by the shore and bring it back to the temple to prepare." }
quests[94871] = { id = 94871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eversong", description = "Magistrix Landra Dawnstrider has sent a request for aid in dealing with the local Lightbloom. While typically harmless, it has recently begun to grow at an incredible rate.\n\nMeet up with Arator in Fairbreeze Village to investigate the threat and provide what assistance you can.", completion = "The wildlife is going out of control!", objectives = "Journey to Fairbreeze Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94909] = { id = 94909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings of Pestilence", description = "<This idol proves the depth of your bond with pestilence.\n\nSpeak with Du'gal at the Altar of Blessings in Amani'Zar to begin worshipping Mot'amra.>", completion = "Many dread Mot'amra. And they aren't wrong to.\n\nBut pestilence, disease, death--these are natural occurrences. Those dat brave their own fear unlock de powerful understandin' of how to cure--or manipulate--these forces.", objectives = "Speak with Du'gal at the Altar of Blessings in Amani'Zar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94932] = { id = 94932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bindings of the Windlord", description = "With Thunderaan risen again as the lord of Skywall, there may indeed be an arrangement you can make in exchange for those wretched implements. But one binding is of no use on its own.\n\nReturn to me with both bindings, and with powerful enough ore to bind them, and I will arrange your audience with Thunderaan the Windlord.", progress = "Yes, {race}?", completion = "And so you return with the bindings in hand. The Firelord shall be very displeased to have lost these.", objectives = "Retrieve both Bindings of the Windlord and 10 Infernal Brimstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94933] = { id = 94933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons in the Void", description = "Ah, you're there!\n\nOur esteemed Magister Umbric has tasked me with wrangling an able-bodied champion to assist him. An apprentice of his, Leona Darkstrider, is investigating the techniques and methods of the illidari.\n\nIt appears her inquiries may have put her in a bit of trouble.\n\nThe Magister can fill you in. He's in K'aresh now, and he's allowed me to open the way for you if you require transportation.", completion = "I'm glad you've chosen to join me here, {name}.", objectives = "Meet up with Umbric in Shand'orah in K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94993] = { id = 94993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventuring in Midnight", description = "The Void encroaches on Azeroth from all sides. Visit the Scouting Map in the Sanctum of Light and choose where you will make your stand.", objectives = "Review the Scouting Map and choose where to begin the Midnight campaign.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94995] = { id = 94995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Dye For", objectives = "Welcome, neighbor! I've got just the thing for you here. These dyes I have here will let you give the decor you buy from our local decor vendors an extra pop of color. Take these and try them out, no charge. Be careful, though. Each only works once.\n\nAnd if you want more, alchemists and scribes can grind up herbs to create pigments, when use those pigments at this dye station to create more dyes. You can also probably find them on the Auction House, if you're not interested in making your own.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95008] = { id = 95008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventuring in Midnight", description = "It's rare that we get to choose our paths in life, but you seem like someone who's seen it all before.\n\n<Soridormi winks.>\n\nDon't dally, this war won't win itself. Go to the Sanctum of Light. Choose where you'll make your first stand.", objectives = "Review the Scouting Map and choose where to begin the Midnight campaign.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95114] = { id = 95114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: A Crimson Summons", completion = "Look at you.... following directions already. \n\nExcellent.", objectives = "Meet with Astalor Bloodsworn in Murder Row.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95175] = { id = 95175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anchoring the Defense", description = "We need your help to activate the Singularity Anchor. \n\nWith proper defenses we can counter enemy assaults long enough to activate the device. If the Anchor is destroyed our efforts will be halted.\n\nDo what you can to help us.", progress = "Have you helped us activate the Singularity Anchor?", completion = "We've neutralized numerous anomalies, but the additonal ones remain. We will prepare for additonal activations.", objectives = "Complete the Stormarion Assault event.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95215] = { id = 95215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Direction", description = "<Your hand burns with felfire as a scroll materializes within your grasp. The seal bears the mark of the Illidari.>\n\n{name}, as leader of the Illidari in Lord Illidan's absence, you must choose your second-in-command.\n\nKayn or Altruis. You can only choose one.\n\nThe chosen shall become your personal champion, and their ideology will color our decisions for the Illidari going forward. No matter who is chosen, our mission remains unchanged.\n\n-Kor'vas Bloodthorn", completion = "I'm glad you selected your second-in-command, {name}.\n\nBut Stormwind mourns today, and we must act.", objectives = "Choose between Kayn and Altruis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
