quests[95242] = { id = 95242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight (81-89) E" }
quests[95245] = { id = 95245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: World Tour", description = "The immediate danger has passed, but there is still much to be done.\n\nGo out and work with our allies to secure what ground we have made against the darkness. Whether it is in Azeroth or beyond, there is still much to be done.", completion = "Back so soon? Impressive!", objectives = "Complete faction features in Midnight zones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95259] = { id = 95259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight (81-89) E" }
quests[95276] = { id = 95276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Push", description = "Our forces are starting to move out to take the fight to Xal'atath. \n\nI've received word there are many areas that you've visited that could still use some aid. \n\nWe must focus our attention on the counter offensive. Can you help those that are in need?", progress = "There's plenty out there that can be done.", completion = "Fine work {name}. \n\nThere's plenty to do now that you've taken care of those issues.", objectives = "Reach level 90.\n\nQuests in Silvermoon City, Eversong Woods, Zul'aman, Harandar, and Voidstorm will now scale to your level.\n\nWorld Quests are now unlocked.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95324] = { id = 95324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War Beyond the Roots", description = "Your actions in Harandar caused quite an uproar. The elders are up in arms. The rootwardens are worried. It's really quite exhausting.\n\nBut there is good news as well. Orweyna has heard rumblings from every corner of the roots. She tells me of haranir who wish to see the world as she does--who feel compelled to seek the goddess beyond the boughs of Harandar.\n\nI will handle things in Harandar. Go to your leaders. Tell them that the haranir are ready to join the fight.", completion = "The haranir seek to join the fight against the Void?\n\nFar be it from me to look a gift hawkstrider in the mouth. Halduron has vouched for both their strength and their tenacity. We shall need a great deal of both, in the battles to come.", objectives = "Bring word to Lor'themar in the Sanctum of Light.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95406] = { id = 95406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Animals", description = "Oh thank goodness you are here!\n\nSome of my precious orange kitties were so eager to play in the neighborhood they've all run off to explore. Please help me find them!", objectives = "Find 10 Lost Cats", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[95407] = { id = 95407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Autumnal Addresses", description = "Race through the checkpoint rings marking the course.", objectives = "Ride through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
