quests[95468] = { id = 95468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hope in the Darkest Corners", description = "I can't imagine what will happen to Quel'Thalas if the Sunwell falls to the forces of the Void.\n\nWe need you out on the battlefield, {name}. Bring hope and heroism to the people across these lands.", completion = "Well done, {name}!", objectives = "Complete various activities in Midnight zones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
